# Let me try a comprehensive entity resolution approach.
# Many titles in some sources have format "Artist - Title" while artist field is NaN.
# Let me extract the actual song title and artist consistently.

import re

def parse_year(y):
    if y is None or (isinstance(y, float) and np.isnan(y)) or str(y).strip()=='' or str(y).lower()=='nan':
        return None
    s = str(y).strip().lstrip("'")
    try:
        n = int(s)
        if n < 100:
            if n <= 25:
                return 2000 + n
            else:
                return 1900 + n
        return n
    except:
        return None

def parse_length(l):
    if l is None or (isinstance(l, float) and np.isnan(l)) or str(l).strip()=='' or str(l).lower() in ('nan','unk.'):
        return None
    s = str(l).strip()
    # Format like "1m 58sec"
    m = re.match(r'(\d+)m\s*(\d+)sec', s)
    if m:
        return int(m.group(1))*60 + int(m.group(2))
    try:
        n = int(s)
        # Could be milliseconds or seconds
        if n > 10000:
            return n // 1000  # likely ms
        return n
    except:
        return None

tracks['year_n'] = tracks['year'].map(parse_year)
tracks['length_n'] = tracks['length'].map(parse_length)
print(tracks[['title','year','year_n','length','length_n']].head(10))

# Extract real title and artist when title is "Artist - Title" pattern
def extract_title_artist(row):
    title = row['title']
    artist = row['artist']
    if pd.isna(title):
        return pd.Series([title, artist])
    # If title has " - " and artist is missing/NaN, treat as "Artist - Title"
    if pd.isna(artist) and ' - ' in str(title):
        parts = str(title).split(' - ', 1)
        if len(parts) == 2:
            return pd.Series([parts[1].strip(), parts[0].strip()])
    return pd.Series([title, artist])

