# Sometimes title may have typos. Let me also try titles with numeric prefixes like "011-I'll Tell You"
# That's a track listing prefix. Let me strip such prefixes.
def strip_prefix(s):
    if pd.isna(s):
        return s
    return re.sub(r'^\s*\d{1,3}\s*[-\.]\s*', '', str(s)).strip()

tracks['t3'] = tracks['t2'].map(strip_prefix)
# Show example
print(tracks[tracks['title'].str.contains('011-', na=False)][['title','t2','t3']].head())

# Source 1: "MM:SS" format
def parse_length_v3(l):
    if l is None:
        return None
    s = str(l).strip()
    if s == '' or s.lower() in ('nan','unk.'):
        return None
    # MM:SS or HH:MM:SS
    if ':' in s:
        parts = s.split(':')
        try:
            parts = [int(p) for p in parts]
            sec = 0
            for p in parts:
                sec = sec * 60 + p
            return sec
        except:
            pass
    m = re.match(r'^(\d+)\s*m\s*(\d+)\s*sec', s)
    if m:
        return int(m.group(1))*60 + int(m.group(2))
    try:
        if '.' in s:
            n = float(s)
            return int(round(n * 60))
        n = int(s)
        if n > 10000:
            return n // 1000
        return n
    except:
        return None

tracks['len_s'] = tracks['length'].map(parse_length_v3)
print(tracks.groupby('source_id')['len_s'].describe())

